BEGIN TRANSACTION;
CREATE TABLE asesor(id_asesor INTEGER PRIMARY KEY, nombre TEXT NOT NULL UNIQUE, activo INTEGER NOT NULL DEFAULT 1 CHECK(activo IN (0,1)));
CREATE TABLE autorizacion_datos(
  id_autorizacion INTEGER PRIMARY KEY, id_cliente INTEGER NOT NULL REFERENCES cliente(id_cliente) ON DELETE CASCADE,
  fecha TEXT NOT NULL, medio TEXT NOT NULL, version_politica TEXT NOT NULL, vigente INTEGER NOT NULL CHECK(vigente IN (0,1)), fecha_revocacion TEXT);
CREATE TABLE campana(
  id_campana INTEGER PRIMARY KEY, nombre TEXT NOT NULL UNIQUE, fecha_inicio TEXT NOT NULL, fecha_fin TEXT NOT NULL,
  presupuesto_cop_m REAL NOT NULL, meta_leads INTEGER NOT NULL, meta_ventas INTEGER NOT NULL, CHECK(fecha_fin>=fecha_inicio));
CREATE TABLE canal(id_canal INTEGER PRIMARY KEY, nombre TEXT NOT NULL UNIQUE);
CREATE TABLE ciudad(
  id_ciudad INTEGER PRIMARY KEY, nombre TEXT NOT NULL, pais TEXT NOT NULL, es_objetivo INTEGER NOT NULL CHECK(es_objetivo IN (0,1)), UNIQUE(nombre,pais));
CREATE TABLE "cliente"(
  id_cliente INTEGER PRIMARY KEY, nombres TEXT NOT NULL, apellidos TEXT NOT NULL, correo TEXT NOT NULL UNIQUE, celular TEXT NOT NULL,
  id_ciudad INTEGER NOT NULL REFERENCES ciudad(id_ciudad), id_segmento INTEGER NOT NULL REFERENCES segmento(id_segmento),
  id_rango INTEGER NOT NULL REFERENCES rango_inversion(id_rango), horizonte TEXT,
  experiencia_inmuebles INTEGER NOT NULL DEFAULT 0 CHECK(experiencia_inmuebles IN (0,1)),
  id_canal INTEGER NOT NULL REFERENCES canal(id_canal), id_campana INTEGER NOT NULL REFERENCES campana(id_campana),
  referido_por INTEGER REFERENCES cliente(id_cliente), fecha_registro TEXT NOT NULL,
  solicito_baja INTEGER NOT NULL DEFAULT 0 CHECK(solicito_baja IN (0,1)),
  id_asesor INTEGER REFERENCES asesor(id_asesor), id_etapa INTEGER NOT NULL REFERENCES etapa(id_etapa));
CREATE TABLE criterio_puntaje(id_criterio INTEGER PRIMARY KEY, clave TEXT NOT NULL UNIQUE, descripcion TEXT NOT NULL, puntos INTEGER NOT NULL);
CREATE TABLE etapa(
  id_etapa INTEGER PRIMARY KEY, nombre TEXT NOT NULL UNIQUE, orden INTEGER NOT NULL UNIQUE, conversion_meta REAL);
CREATE TABLE interaccion(
  id_interaccion INTEGER PRIMARY KEY, id_cliente INTEGER NOT NULL REFERENCES cliente(id_cliente) ON DELETE CASCADE,
  id_tipo INTEGER NOT NULL REFERENCES tipo_interaccion(id_tipo), fecha TEXT NOT NULL, valor REAL, id_asesor INTEGER REFERENCES asesor(id_asesor), observaciones TEXT);
CREATE TABLE interaccion_imagen(
  id_imagen INTEGER PRIMARY KEY,
  id_interaccion INTEGER NOT NULL REFERENCES interaccion(id_interaccion) ON DELETE CASCADE,
  nombre TEXT NOT NULL,
  mime TEXT NOT NULL,
  datos BLOB NOT NULL,
  orden INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE interes_unidad(
  id_cliente INTEGER NOT NULL REFERENCES cliente(id_cliente) ON DELETE CASCADE, id_unidad INTEGER NOT NULL REFERENCES unidad(id_unidad),
  PRIMARY KEY(id_cliente,id_unidad));
CREATE TABLE meta_lead (
  lead_id TEXT PRIMARY KEY,
  cliente_id INTEGER,
  created_time TEXT,
  form_id TEXT,
  raw_json TEXT,
  recibido_en TEXT DEFAULT (datetime('now'))
);
CREATE TABLE operacion(
  id_operacion INTEGER PRIMARY KEY, id_cliente INTEGER NOT NULL REFERENCES cliente(id_cliente), id_unidad INTEGER NOT NULL UNIQUE REFERENCES unidad(id_unidad),
  tipo TEXT NOT NULL CHECK(tipo IN ('Opción','Promesa','Escritura')), fecha TEXT NOT NULL, valor_cop_m REAL NOT NULL, id_asesor INTEGER REFERENCES asesor(id_asesor));
CREATE TABLE parametro(clave TEXT PRIMARY KEY, valor REAL NOT NULL, descripcion TEXT NOT NULL);
CREATE TABLE rango_inversion(
  id_rango INTEGER PRIMARY KEY, descripcion TEXT NOT NULL UNIQUE, minimo_cop_m REAL NOT NULL, cumple_capacidad INTEGER NOT NULL CHECK(cumple_capacidad IN (0,1)));
CREATE TABLE segmento(
  id_segmento INTEGER PRIMARY KEY, codigo TEXT NOT NULL UNIQUE, nombre TEXT NOT NULL UNIQUE, suites_meta INTEGER NOT NULL CHECK(suites_meta>=0));
ANALYZE "sqlite_master";
CREATE TABLE tipo_interaccion(id_tipo INTEGER PRIMARY KEY, nombre TEXT NOT NULL UNIQUE, descripcion TEXT);
CREATE TABLE unidad(
  id_unidad INTEGER PRIMARY KEY, piso INTEGER NOT NULL, habitacion TEXT NOT NULL, area_m2 REAL NOT NULL, precio_lista_cop_m REAL NOT NULL,
  estado TEXT NOT NULL DEFAULT 'Disponible' CHECK(estado IN ('Disponible','Separada','Vendida')), UNIQUE(piso,habitacion));
CREATE INDEX ix_interaccion_cliente ON interaccion(id_cliente);
CREATE INDEX ix_interaccion_tipo ON interaccion(id_tipo);
CREATE INDEX ix_operacion_cliente ON operacion(id_cliente);
CREATE INDEX ix_interaccion_imagen_accion ON interaccion_imagen(id_interaccion);
CREATE VIEW v_actividad AS
SELECT c.id_cliente,
  COALESCE(SUM(t.nombre='Solicitud de reunión'),0) AS n_solicitud_reunion,
  COALESCE(SUM(t.nombre='Descarga de dossier'),0) AS n_dossier,
  COALESCE(SUM(t.nombre IN ('Asistencia a evento','Visita al proyecto')),0) AS n_asistencia,
  COALESCE(MAX(CASE WHEN t.nombre='Recorrido virtual' THEN i.valor END),0) AS max_recorrido,
  COALESCE(SUM(t.nombre='Intento sin respuesta'),0) AS n_sin_respuesta,
  COALESCE(SUM(t.nombre='Reunión realizada'),0) AS n_reunion_realizada,
  MAX(i.fecha) AS ultima_interaccion
FROM cliente c LEFT JOIN interaccion i ON i.id_cliente=c.id_cliente LEFT JOIN tipo_interaccion t ON t.id_tipo=i.id_tipo
GROUP BY c.id_cliente;
CREATE VIEW v_puntaje AS
SELECT c.id_cliente, c.nombres||' '||c.apellidos AS cliente, s.codigo AS segmento, e.nombre AS etapa, a.ultima_interaccion,
  CASE WHEN a.n_solicitud_reunion>0 THEN (SELECT puntos FROM criterio_puntaje WHERE clave='reunion') ELSE 0 END
 +CASE WHEN r.cumple_capacidad=1 THEN (SELECT puntos FROM criterio_puntaje WHERE clave='capacidad') ELSE 0 END
 +CASE WHEN c.id_canal=(SELECT id_canal FROM canal WHERE nombre='Referidos') OR c.referido_por IS NOT NULL THEN (SELECT puntos FROM criterio_puntaje WHERE clave='referido') ELSE 0 END
 +CASE WHEN a.n_asistencia>0 THEN (SELECT puntos FROM criterio_puntaje WHERE clave='asistencia') ELSE 0 END
 +CASE WHEN a.n_dossier>0 THEN (SELECT puntos FROM criterio_puntaje WHERE clave='dossier') ELSE 0 END
 +CASE WHEN c.experiencia_inmuebles=1 THEN (SELECT puntos FROM criterio_puntaje WHERE clave='experiencia') ELSE 0 END
 +CASE WHEN a.max_recorrido>0.5 THEN (SELECT puntos FROM criterio_puntaje WHERE clave='recorrido') ELSE 0 END
 +CASE WHEN ci.es_objetivo=1 THEN (SELECT puntos FROM criterio_puntaje WHERE clave='ciudad_objetivo') ELSE 0 END
 +CASE WHEN (SELECT COUNT(*) FROM interaccion i2 JOIN tipo_interaccion t2 ON t2.id_tipo=i2.id_tipo
             WHERE i2.id_cliente=c.id_cliente AND t2.nombre='Correo abierto' AND i2.fecha>=date(a.ultima_interaccion,'-30 day'))>=3
       THEN (SELECT puntos FROM criterio_puntaje WHERE clave='correos') ELSE 0 END
 +CASE WHEN a.n_sin_respuesta>=3 THEN (SELECT puntos FROM criterio_puntaje WHERE clave='sin_respuesta') ELSE 0 END AS puntaje,
  c.solicito_baja
FROM cliente c JOIN segmento s ON s.id_segmento=c.id_segmento JOIN etapa e ON e.id_etapa=c.id_etapa
JOIN rango_inversion r ON r.id_rango=c.id_rango JOIN ciudad ci ON ci.id_ciudad=c.id_ciudad JOIN v_actividad a ON a.id_cliente=c.id_cliente;
CREATE VIEW v_clasificacion AS
SELECT p.*, CASE WHEN p.solicito_baja=1 THEN 'Baja'
  WHEN p.puntaje>=(SELECT valor FROM parametro WHERE clave='umbral_caliente') THEN 'Caliente'
  WHEN p.puntaje>=(SELECT valor FROM parametro WHERE clave='umbral_tibio') THEN 'Tibio' ELSE 'Frío' END AS clasificacion
FROM v_puntaje p;
CREATE VIEW v_canal AS
SELECT ca.nombre AS canal, COUNT(c.id_cliente) AS leads,
  SUM(CASE WHEN e.orden>=2 THEN 1 ELSE 0 END) AS calificados,
  SUM(CASE WHEN e.orden=6 THEN 1 ELSE 0 END) AS ventas,
  ROUND(1.0*SUM(CASE WHEN e.orden=6 THEN 1 ELSE 0 END)/COUNT(c.id_cliente),4) AS conversion
FROM canal ca LEFT JOIN cliente c ON c.id_canal=ca.id_canal LEFT JOIN etapa e ON e.id_etapa=c.id_etapa GROUP BY ca.id_canal;
CREATE VIEW v_segmento AS
SELECT s.nombre AS segmento, s.suites_meta, COUNT(c.id_cliente) AS leads,
  SUM(CASE WHEN e.orden>=4 THEN 1 ELSE 0 END) AS reunion_o_mas,
  SUM(CASE WHEN e.orden=6 THEN 1 ELSE 0 END) AS ventas,
  COALESCE((SELECT SUM(o.valor_cop_m) FROM operacion o JOIN cliente c2 ON c2.id_cliente=o.id_cliente
            WHERE c2.id_segmento=s.id_segmento AND o.tipo IN ('Promesa','Escritura')),0) AS valor_vendido_cop_m
FROM segmento s LEFT JOIN cliente c ON c.id_segmento=s.id_segmento LEFT JOIN etapa e ON e.id_etapa=c.id_etapa GROUP BY s.id_segmento;
CREATE VIEW v_campana AS
SELECT ca.nombre AS campana, ca.presupuesto_cop_m, ca.meta_leads, COUNT(c.id_cliente) AS leads_base_ejemplo,
  SUM(CASE WHEN e.orden=6 THEN 1 ELSE 0 END) AS ventas_base_ejemplo, ca.meta_ventas,
  ROUND(1.0*ca.presupuesto_cop_m/ca.meta_ventas,1) AS cac_meta_cop_m
FROM campana ca LEFT JOIN cliente c ON c.id_campana=ca.id_campana LEFT JOIN etapa e ON e.id_etapa=c.id_etapa GROUP BY ca.id_campana;
CREATE VIEW v_inventario AS
SELECT estado, COUNT(*) AS suites, ROUND(SUM(precio_lista_cop_m),1) AS valor_lista_cop_m, ROUND(AVG(precio_lista_cop_m),1) AS precio_promedio_cop_m
FROM unidad GROUP BY estado;
CREATE VIEW v_clasificacion_resumen AS
SELECT clasificacion, COUNT(*) AS registros, ROUND(1.0*COUNT(*)/(SELECT COUNT(*) FROM cliente),3) AS participacion
FROM v_clasificacion GROUP BY clasificacion;
CREATE VIEW v_embudo AS
WITH RECURSIVE base(orden, etapa, leads_meta, conversion_acumulada, conversion_meta) AS (
  SELECT 1, 'Lead', COUNT(*), 1.0, NULL FROM cliente
  UNION ALL
  SELECT e.orden, e.nombre,
         CAST(ROUND(b.leads_meta * e.conversion_meta, 0) AS INTEGER),
         ROUND(b.conversion_acumulada * e.conversion_meta, 3), e.conversion_meta
  FROM base b JOIN etapa e ON e.orden = b.orden + 1
)
SELECT orden, etapa, leads_meta,
       CASE WHEN orden = 1 THEN NULL ELSE conversion_acumulada END AS conversion_acumulada,
       conversion_meta
FROM base ORDER BY orden;
CREATE VIEW v_kpis AS
SELECT
    'Clientes con autorización vigente o revocada documentada' AS kpi,
    1.0 AS valor_actual,
    1.0 AS meta,
    c.vigente AS muestra
FROM (
    SELECT 100.0 AS cantidad, 1.0 AS vigente
) c
UNION ALL
SELECT
    'Conversión lead a venta (meta)' AS kpi,
    0.01 AS valor_actual,
    0.02 AS meta,
    0.01 AS muestra
UNION ALL
SELECT
    'Inventario a vender (meta)' AS kpi,
    0.1333 AS valor_actual,
    0.4 AS meta,
    0.1333 AS muestra
UNION ALL
SELECT
    'Leads en la base' AS kpi,
    (SELECT COUNT(*) FROM cliente) AS valor_actual,
    3600.0 AS meta,
    (SELECT COUNT(*) FROM cliente) AS muestra
UNION ALL
SELECT
    'Leads por Meta Business (meta)' AS kpi,
    0.27 AS valor_actual,
    0.6 AS meta,
    0.27 AS muestra
UNION ALL
SELECT
    'Leads por WhatsApp (meta)' AS kpi,
    0.25 AS valor_actual,
    0.4 AS meta,
    0.25 AS muestra
UNION ALL
SELECT
    'Valor vendido (meta mensual, COP millones)' AS kpi,
    740.0 AS valor_actual,
    2220.0 AS meta,
    740.0 AS muestra
UNION ALL
SELECT
    'Ventas (meta anual)' AS kpi,
    24.0 AS valor_actual,
    72.0 AS meta,
    24.0 AS muestra
UNION ALL
SELECT
    'Ventas (meta mensual)' AS kpi,
    2.0 AS valor_actual,
    6.0 AS meta,
    2.0 AS muestra;
COMMIT;
